package com.corecs.dbms.executor;
import com.corecs.dbms.model.*;import com.corecs.dbms.storage.MiniStorageEngine;import org.springframework.stereotype.Service;import java.util.*;
@Service public class MiniQueryExecutor {private final MiniStorageEngine storage;public MiniQueryExecutor(MiniStorageEngine s){storage=s;}
 public QueryResult execute(ParsedQuery q,List<String> tokens){List<QueryStep> steps=new ArrayList<>();steps.add(new QueryStep("Tokenizer","Converted SQL into "+tokens.size()+" tokens"));steps.add(new QueryStep("Parser","Built a structured "+q.type()+" query model"));
 switch(q.type()){case "CREATE":return create(q,tokens,steps);case "INSERT":return insert(q,tokens,steps);case "SELECT":return select(q,tokens,steps);case "UPDATE":return update(q,tokens,steps);case "DELETE":return delete(q,tokens,steps);default:throw new IllegalArgumentException("Unsupported query");}}
 private QueryResult create(ParsedQuery q,List<String> tok,List<QueryStep> st){List<ColumnDef> c=q.columns().stream().map(x->{var p=x.split(":");return new ColumnDef(p[0],p.length>1?p[1]:"STRING",p.length>2);}).toList();storage.create(q.table(),c);st.add(new QueryStep("Storage","Created table metadata"));return result("Table "+q.table()+" created",List.of(),List.of(),storage.pages(storage.get(q.table())),tok,st,false);}
 private QueryResult insert(ParsedQuery q,List<String> tok,List<QueryStep> st){var t=storage.get(q.table());if(q.values().getFirst().size()!=t.columns().size())throw new IllegalArgumentException("INSERT value count must match column count");t.rows().add(new ArrayList<>(q.values().getFirst()));storage.rebuildIndex(t);st.add(new QueryStep("Storage","Appended record to a page"));return result("1 row inserted",t.columns().stream().map(ColumnDef::name).toList(),List.of(q.values().getFirst()),storage.pages(t),tok,st,false);}
 private QueryResult select(ParsedQuery q,List<String> tok,List<QueryStep> st){var t=storage.get(q.table());List<List<String>> rows=new ArrayList<>();List<String> cols=q.columns().contains("*")?t.columns().stream().map(ColumnDef::name).toList():q.columns();boolean idx=q.where()!=null&&q.where().column().equalsIgnoreCase("id")&&storage.index().find(t.name(),q.where().value())!=null;st.add(new QueryStep("Query Plan",idx?"Index lookup on id":"Full table scan"));for(var r:t.rows())if(matches(t,r,q.where()))rows.add(project(t,r,cols));st.add(new QueryStep("Filter",rows.size()+" matching row(s)"));return result(rows.size()+" row(s) returned",cols,rows,storage.pages(t),tok,st,idx);}
 private QueryResult update(ParsedQuery q,List<String> tok,List<QueryStep> st){var t=storage.get(q.table());int n=0;for(var r:t.rows())if(matches(t,r,q.where())){for(int i=0;i<q.setColumns().size();i++){int c=col(t,q.setColumns().get(i));r.set(c,q.setValues().get(i));}n++;}storage.rebuildIndex(t);st.add(new QueryStep("Storage","Updated matching records"));return result(n+" row(s) updated",t.columns().stream().map(ColumnDef::name).toList(),List.of(),storage.pages(t),tok,st,false);}
 private QueryResult delete(ParsedQuery q,List<String> tok,List<QueryStep> st){var t=storage.get(q.table());int before=t.rows().size();t.rows().removeIf(r->matches(t,r,q.where()));int n=before-t.rows().size();storage.rebuildIndex(t);st.add(new QueryStep("Storage","Removed matching records"));return result(n+" row(s) deleted",t.columns().stream().map(ColumnDef::name).toList(),List.of(),storage.pages(t),tok,st,false);}
 private boolean matches(TableDef t,List<String> r,WhereClause w){if(w==null)return true;String actual=r.get(col(t,w.column())), expected=w.value();return switch(w.operator()){case "="->actual.equals(expected);case ">"->num(actual)>num(expected);case "<"->num(actual)<num(expected);case ">="->num(actual)>=num(expected);case "<="->num(actual)<=num(expected);default->throw new IllegalArgumentException("Unsupported WHERE operator: "+w.operator());};}
 private int num(String x){try{return Integer.parseInt(x);}catch(Exception e){throw new IllegalArgumentException("Numeric WHERE comparison requires integer values");}}
 private int col(TableDef t,String name){for(int i=0;i<t.columns().size();i++)if(t.columns().get(i).name().equalsIgnoreCase(name))return i;throw new IllegalArgumentException("Column not found: "+name);}
 private List<String> project(TableDef t,List<String> r,List<String> cols){List<String> o=new ArrayList<>();for(String c:cols)o.add(r.get(col(t,c)));return o;}
 private QueryResult result(String m,List<String> c,List<List<String>> r,List<PageView> p,List<String> tok,List<QueryStep> s,boolean i){return new QueryResult(m,c,r,p,tok,s,i);}
}
